using System.Reflection;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;

namespace PaymentAuthorization.IntegrationTest.Architecture;

public class LayerDependencyTests
{
    // Allow-list of the language core: no I/O, network, persistence or environment access.
    private static readonly HashSet<string> CoreNamespaces =
    [
        "System",
        "System.Collections.Generic",
        "System.Diagnostics.CodeAnalysis",
        "System.Runtime.CompilerServices",
        "System.Threading",
        "System.Threading.Tasks",
    ];

    private static readonly HashSet<string> CoreTypesNotAllowed =
    [
        "System.Console", "System.Environment", "System.AppDomain", "System.Activator",
    ];

    private static readonly Assembly Domain = typeof(Money).Assembly;
    private static readonly Assembly Application = typeof(AuthorizePayment).Assembly;

    [Fact]
    public void Domain_depends_only_on_itself_and_the_language_core() =>
        AssertOnlyDependsOn(Domain);

    [Fact]
    public void Application_depends_only_on_itself_Domain_and_the_language_core() =>
        AssertOnlyDependsOn(Application, Domain.GetName().Name!);

    private static void AssertOnlyDependsOn(Assembly layer, params string[] allowedAssemblies)
    {
        var violations = ReferencedTypes(layer)
            .Where(t => !IsAllowed(t, layer.GetName().Name!, allowedAssemblies))
            .Select(t => $"{layer.GetName().Name} -> {t.Namespace}.{t.Name} [{t.Assembly}]")
            .Distinct()
            .OrderBy(v => v)
            .ToList();

        Assert.True(violations.Count == 0, "Violations:" + Environment.NewLine + string.Join(Environment.NewLine, violations));
    }

    private static bool IsAllowed((string Namespace, string Name, string Assembly) type, string self, string[] allowedAssemblies)
    {
        if (type.Assembly == self || allowedAssemblies.Contains(type.Assembly)) return true;
        if (CoreTypesNotAllowed.Contains($"{type.Namespace}.{type.Name}")) return false;
        return CoreNamespaces.Contains(type.Namespace);
    }

    private static IEnumerable<(string Namespace, string Name, string Assembly)> ReferencedTypes(Assembly assembly)
    {
        using var stream = File.OpenRead(assembly.Location);
        using var pe = new PEReader(stream);
        var reader = pe.GetMetadataReader();

        foreach (var handle in reader.TypeReferences)
        {
            var reference = reader.GetTypeReference(handle);
            if (reference.ResolutionScope.Kind != HandleKind.AssemblyReference) continue; // nested types follow their parent
            var scope = reader.GetAssemblyReference((AssemblyReferenceHandle)reference.ResolutionScope);
            yield return (reader.GetString(reference.Namespace), reader.GetString(reference.Name), reader.GetString(scope.Name));
        }
    }
}
